[Expected Approach] Hashing - O(n) Time and O(n) SpaceThe idea is to insert all array elements into a hash set while simultaneously finding the minimum and maximum values. Since a set stores only unique elements, its size represents the number of distinct elements present in the array. The total number of elements that should exist in the range is (maxm − minm + 1). The difference between this total range size and the set size gives the count of missing elements.
            C++

    #include <iostream>
#include <vector>
#include <unordered_set>
#include <limits.h>
using namespace std;

// Function to count numbers to be added
int countNum(vector<int> &arr)
{
    unordered_set<int> s;
    int count = 0, maxm = INT_MIN, minm = INT_MAX;

    // Make a hash of elements
    // and store minimum and maximum element
    for (int i = 0; i < arr.size(); i++) {
        s.insert(arr[i]);
        if (arr[i] < minm)
            minm = arr[i];
        if (arr[i] > maxm)
            maxm = arr[i];
    }

    // The missing element count
    return (maxm - minm + 1) - s.size();
}

int main()
{
    vector<int> arr = { 3, 5, 8, 6 };
